diff --git a/index.js b/index.js
index 5ecd392..8b981ae 100644
--- a/index.js
+++ b/index.js
@@ -81,10 +81,22 @@ export default function pLimit(concurrency) {
 					return;
 				}

-				const abortError = AbortSignal.abort().reason;
-
+				// Detach every pending item before rejecting any of them, so the
+				// cleanup cannot be interrupted part-way: each item is removed
+				// exactly once and none are retained if a rejection throws.
+				const pendingItems = [];
 				while (queue.size > 0) {
-					queue.dequeue().reject(abortError);
+					pendingItems.push(queue.dequeue());
+				}
+
+				// A plain `Error` rather than `AbortSignal.abort().reason`, as a
+				// `DOMException` is not recognized as an error by assertion
+				// libraries and other `Object.prototype.toString` based checks.
+				const abortError = new Error('The queue was cleared');
+				abortError.name = 'AbortError';
+
+				for (const queueItem of pendingItems) {
+					queueItem.reject(abortError);
 				}
 			},
 		},
